def process_orders(batch):
    if not batch:
        return []

    succeeded_ids = []
    for item in batch:
        if not isinstance(item, dict):
            continue

        payment_info = item.get('payment_method', {})
        validator = payment_info.get('validator')
        amount = item.get('amount', 0)

        if 'id' in item and validator and validator() and amount > 0:
            succeeded_ids.append(item['id'])

    return succeeded_ids
